wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

const MAX_QUESTION_BYTES: usize = 512;
const NO_MATCH: &str = "no knowledge base entries matched this question";

/// Truncate to at most MAX_QUESTION_BYTES bytes, on a char boundary.
/// Byte length bounds character count, so this satisfies a character-count
/// ensures as well as a byte-count one.
fn bound_question(question: String) -> String {
    if question.len() <= MAX_QUESTION_BYTES {
        return question;
    }
    let mut end = MAX_QUESTION_BYTES;
    while !question.is_char_boundary(end) {
        end -= 1;
    }
    question[..end].to_string()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(query.query.question);

        let mut knowledge = crate::aap::caps::kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_MATCH.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
